/* The wrapper itself: strip the host's card, but NOT its width. Layout > Max width in the module
   settings (480/640/768/960/Full) is a max-width on THIS element, and the previous version of this
   rule overrode it with max-width:none!important - so picking 960 did nothing at all. */
.mf-form-wrapper:has(.mfp-rws){background:transparent!important;border:0!important;
  border-radius:0!important;box-shadow:none!important;padding:0!important}
/* The boxes INSIDE it have their own measures, and those are what squeezed the design. */
.mf-form-wrapper:has(.mfp-rws) > .mf-form-inner,
.mf-form-wrapper:has(.mfp-rws) .mf-form,
.mf-form-wrapper:has(.mfp-rws) .mf-fields-container{background:transparent!important;
  border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;
  margin:0!important;max-width:none!important;width:100%!important}

/* page ------------------------------------------------------------------ */
.mfp.mfp-rws.mfp-native-generated {container-type:inline-size;font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif!important;color:var(--rws-text)}
/* min-h-screen on the mock's <main>: the panel is as tall as the window, which is what gives the
   photograph its 52% and leaves the team list room. Without it the aside collapsed to the form's
   height and clipped Lena Kovacs. */
.mfp.mfp-rws.mfp-native-generated .rws-grid{display:grid;grid-template-columns:1fr;max-width:1152px;margin:0 auto;
  min-height:100vh;background:var(--rws-page)}
/* The mock hides the panel below lg (1024px). A CONTAINER query, not a media query: the form is
   embedded in a CMS pane whose width has nothing to do with the viewport's. */
@container (min-width:1024px){.mfp.mfp-rws.mfp-native-generated .rws-grid{grid-template-columns:420px 1fr}}

/* left panel ------------------------------------------------------------ */
